def parsear_duracion(s):
    minutos = 0
    partes = s.split('h')
    if len(partes) > 1:
        minutos += int(partes[1]) * 60
    partes = partes[0].split('m')
    if len(partes) > 1:
        minutos += int(partes[1])
    return minutos

def aplanar(lista):
    resultado = []
    for elemento in lista:
        if isinstance(elemento, list):
            resultado.extend(aplanar(elemento))
        else:
            resultado.append(elemento)
    return resultado

def buscar(lista, x):
    left = 0
    right = len(lista) - 1
    while left <= right:
        mid = (left + right) // 2
        if lista[mid] == x:
            return mid
        elif lista[mid] < x:
            left = mid + 1
        else:
            right = mid - 1
    return -1

def agrupar_por(items, clave):
    resultado = {}
    for item in items:
        valor_clave = item[clave]
        if valor_clave not in resultado:
            resultado[valor_clave] = []
        resultado[valor_clave].append(item)
    return resultado

def contar_palabras(texto):
    import string
    texto = texto.lower()
    texto = texto.translate(str.maketrans('', '', string.punctuation))
    palabras = texto.split()
    return {palabra: palabras.count(palabra) for palabra in palabras}

def rotar(lista, n):
    if not lista:
        return []
    longitud = len(lista)
    n = n % longitud
    if n < 0:
        n += longitud
    return lista[-n:] + lista[:-n]

def a_romano(n):
    valores = [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'),
        (1, 'I')
    ]
    romano = ''
    for valor, simbolo in valores:
        while n >= valor:
            romano += simbolo
            n -= valor
    return romano

def desde_romano(s):
    valores = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    anterior = 0
    for char in s:
        actual = valores[char]
        if actual > anterior:
            total += actual - anterior
        else:
            total += actual
        anterior = actual
    return total

def mayor_racha(lista):
    if not lista:
        return None
    max_elemento = lista[0]
    max_longitud = 1
    current_elemento = lista[0]
    current_longitud = 1
    for i in range(1, len(lista)):
        if lista[i] == current_elemento:
            current_longitud += 1
            if current_longitud > max_longitud:
                max_elemento = current_elemento
                max_longitud = current_longitud
        else:
            current_elemento = lista[i]
            current_longitud = 1
    return (max_elemento, max_longitud)

def primos(n):
    if n < 2:
        return []
    primos = []
    for num in range(2, n + 1):
        es_primo = True
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                es_primo = False
                break
        if es_primo:
            primos.append(num)
    return primos

def mcd(a, b):
    while b != 0:
        a, b = b, a % b
    return a

def fusionar(intervalos):
    if not intervalos:
        return []
    # Ordenar los intervalos por el inicio
    intervalos.sort()
    fusionados = [intervalos[0]]
    for intervalo in intervalos[1:]:
        ultimo = fusionados[-1]
        if intervalo[0] <= ultimo[1]:
            # Fusionar los intervalos
            fusionados[-1] = (min(ultimo[0], intervalo[0]), max(ultimo[1], intervalo[1]))
        else:
            fusionados.append(intervalo)
    return fusionados

def comprimir(s):
    if len(s) <= 2:
        return s
    compressed = []
    count = 1
    for i in range(1, len(s)):
        if s[i] == s[i-1]:
            count += 1
        else:
            compressed.append(s[i-1] + str(count))
            count = 1
    compressed.append(s[-1] + str(count))
    return min(s, ''.join(compressed))

def balanceado(s):
    stack = []
    pairs = {'{': '}', '[': ']', '()': ''}
    for char in s:
        if char in pairs:
            stack.append(char)
        elif char in pairs.values():
            if not stack or pairs[stack.pop()] != char:
                return False
    return not stack

def raiz_digital(n):
    while n >= 10:
        suma = sum(int(d) for d in str(n))
        n = suma
    return n

def sin_duplicados(lista):
    resultado = []
    elementos_vistos = set()
    for elemento in lista:
        if elemento not in elementos_vistos:
            resultado.append(elemento)
            elementos_vistos.add(elemento)
    return resultado

def n_esimo_mayor(lista, n):
    distintos = list(set(lista))
    distintos.sort(reverse=True)
    if n <= len(distintos):
        return distintos[n-1]
    else:
        return None

def formatear_bytes(n):
    if n < 1024:
        return f"{n} B"
    elif n < 1024**2:
        return f"{n / 1024:.1f} KB"
    elif n < 1024**3:
        return f"{n / 1024**2:.1f} MB"
    else:
        return f"{n / 1024**3:.1f} GB"
